            }
            _ = self.concurrent_tasks.push(task);
            _ = self.wakeup();
    }

pub fn enqueueTaskConcurrentBatch(self: *EventLoop, batch: ConcurrentTask.Queue.Batch) void {
            if (comptime Environment.allow_assert) {
                if (self.virtual_machine.has_terminated) {
                    _ = @panic("EventLoop.enqueueTaskConcurrent: VM has terminated");
                }
            }
            if (comptime Environment.isDebug) {
                _ = log("enqueueTaskConcurrentBatch({d})", .{ batch.count });
            }
            _ = self.concurrent_tasks.pushBatch(batch.front.?, batch.last.?);
            _ = self.wakeup();
    }

pub fn refConcurrently(self: *EventLoop) void {
            _ = self.concurrent_ref.fetchAdd(1, .seq_cst);
            _ = self.wakeup();
    }

pub fn unrefConcurrently(self: *EventLoop) void {
            _ = self.concurrent_ref.fetchSub(1, .seq_cst);
            _ = self.wakeup();
    }

pub fn release(self: *EventLoop) void {
            _ = self.tasks.deinit();
            _ = self.immediate_tasks.clearAndFree(bun.default_allocator);
            _ = self.next_immediate_tasks.clearAndFree(bun.default_allocator);
    }

pub fn deinit(self: *EventLoop) void {
            _ = (if (comptime @typeInfo(@TypeOf(self)) == .pointer) (self) else &(self)).release();
    }
